  s2_t:{ca:"Permacultura i <em>hort</em>",es:"Permacultura y <em>huerto</em>",en:"Permaculture and <em>garden</em>",eu:"Permakultura eta <em>baratzea</em>",ga:"Buanchultúr agus <em>gairdín</em>"},
  s2_p:{ca:"Disseny de sistemes, hort ecològic, compostatge i sobirania alimentària.",es:"Diseño de sistemas, huerto ecológico, compostaje y soberanía alimentaria.",en:"Systems design, organic gardening, composting and food sovereignty.",eu:"Sistemen diseinua, baratze ekologikoa, konpostajea eta elikadura-subiranotasuna.",ga:"Dearadh córas, gairneoireacht orgánach, múiríniú agus ceannasacht bia."},
  s3_k:{ca:"Què fem · Comunitat",es:"Qué hacemos · Comunidad",en:"What we do · Community",eu:"Zer egiten dugun · Komunitatea",ga:"A ndéanaimid · Pobal"},
  s3_t:{ca:"Voluntariats i vida <em>compartida</em>",es:"Voluntariados y vida <em>compartida</em>",en:"Volunteering and a <em>shared</em> life",eu:"Boluntariotza eta bizitza <em>partekatua</em>",ga:"Obair dheonach agus saol <em>roinnte</em>"},
  s3_p:{ca:"Queda't una temporada: aprèn fent, treballa la terra i forma part del dia a dia de la casa.",es:"Quédate una temporada: aprende haciendo, trabaja la tierra y forma parte del día a día de la casa.",en:"Stay for a season: learn by doing, work the land and become part of daily life at the house.",eu:"Geratu denboraldi batez: ikasi eginez, landu lurra eta izan etxeko eguneroko bizitzaren parte.",ga:"Fan ar feadh séasúir: foghlaim trí dhéanamh, oibrigh an talamh agus bí mar chuid de shaol laethúil an tí."},
  s3_link:{ca:"Saber-ne més",es:"Saber más",en:"Find out more",eu:"Gehiago jakin",ga:"Tuilleadh eolais"},
