  hi_s4_p:{ca:"Durant segles el lloc resta vinculat al Solsonès i a l'òrbita del vescomtat de Cardona.",es:"Durante siglos el lugar permanece vinculado al Solsonès y a la órbita del vizcondado de Cardona.",en:"For centuries the place remains tied to the Solsonès and to the orbit of the viscounty of Cardona.",eu:"Mendeetan zehar lekua Solsonèsi eta Cardonako bizkondetzaren orbitari lotuta dago.",ga:"Ar feadh na gcéadta bliain fanann an áit ceangailte leis an Solsonès agus le fithis bhiocuntacht Cardona."},
  hi_s4_c:{ca:"El castell de Cardona, seu del vescomtat",es:"El castillo de Cardona, sede del vizcondado",en:"Cardona castle, seat of the viscounty",eu:"Cardonako gaztelua, bizkondetzaren egoitza",ga:"Caisleán Cardona, suíomh na biocuntachta"},
