  hi_s7_p:{ca:"Les fotografies de Josep Salvany documenten una comunitat rural viva al voltant de l'església i la rectoria.",es:"Las fotografías de Josep Salvany documentan una comunidad rural viva alrededor de la iglesia y la rectoría.",en:"Josep Salvany's photographs document a living rural community around the church and the rectory.",eu:"Josep Salvanyren argazkiek eliza eta abadetxearen inguruko landa-komunitate bizia dokumentatzen dute.",ga:"Doiciméadaíonn grianghraif Josep Salvany pobal tuaithe beo timpeall an tséipéil agus theach an pharóiste."},
  hi_s7_c:{ca:"Llinars de l'Aiguadora · 1919, J. Salvany",es:"Llinars de l'Aiguadora · 1919, J. Salvany",en:"Llinars de l'Aiguadora · 1919, J. Salvany",eu:"Llinars de l'Aiguadora · 1919, J. Salvany",ga:"Llinars de l'Aiguadora · 1919, J. Salvany"},
  hi_s8_y:{ca:"Segle XX",es:"Siglo XX",en:"20th century",eu:"XX. mendea",ga:"an 20ú haois"},
  hi_s8_t:{ca:"Èxode rural",es:"Éxodo rural",en:"Rural exodus",eu:"Landa-exodoa",ga:"Eisimirce tuaithe"},
  hi_s8_p:{ca:"Com a bona part del món rural pirinenc, la població marxa cap a les ciutats. L'església i la rectoria es van quedant buides i en silenci.",es:"Como buena parte del mundo rural pirenaico, la población se marcha a las ciudades. La iglesia y la rectoría se van quedando vacías y en silencio.",en:"Like much of the rural Pyrenees, the population leaves for the cities. The church and the rectory gradually fall empty and silent.",eu:"Pirinioetako landa-mundu gehienean bezala, biztanleria hirietara joaten da. Eliza eta abadetxea hutsik eta isilik geratzen dira pixkanaka.",ga:"Cosúil le cuid mhór de na Piréiní tuaithe, imíonn an daonra chuig na cathracha. Folmhaítear an séipéal agus teach an pharóiste de réir a chéile agus titeann siad ina dtost."},
  hi_s8_c:{ca:"L'antiga rectoria, abans de Cal Niu",es:"La antigua rectoría, antes de Cal Niu",en:"The old rectory, before Cal Niu",eu:"Antzinako abadetxea, Cal Niu baino lehen",ga:"An seanteach paróiste, roimh Cal Niu"},
